tasks.starter:
function fuelStatus(fuel) {
  // return a text depending on the conditions
}

console.log(fuelStatus(0));
console.log(fuelStatus(15));
console.log(fuelStatus(80));

tasks.solution:
function fuelStatus(fuel) {
  // return a text depending on the conditions
  if (fuel === 0) {
    return "empty";
  }
  if (fuel < 30) {
    return "low";
  }
  return "enough";
}

console.log(fuelStatus(0));
console.log(fuelStatus(15));
console.log(fuelStatus(80));

