tasks.solution:
function launchMessage(ship, countdown = 3) {
  // return the text
  return `${ship} launches in ${countdown} seconds!`;
}

console.log(launchMessage("Eagle"));
console.log(launchMessage("Falcon", 10));

challenge.starter:
function maxOf(numbers) {
  // find and return the largest number with a loop
}

console.log(maxOf([4, 18, 7, 12]));

challenge.solution:
function maxOf(numbers) {
  // find and return the largest number with a loop
  let max = numbers[0];
  for (const n of numbers) {
    if (n > max) {
      max = n;
    }
  }
  return max;
}

console.log(maxOf([4, 18, 7, 12]));

