console.log("Boss health:", boss);

project_task.solution:
// write the attack function
function attack(enemyHealth, damage = 10) {
  const result = enemyHealth - damage;
  if (result < 0) {
    return 0;
  }
  return result;
}

let boss = 100;
// attack the boss twice
boss = attack(boss, 35);
boss = attack(boss);

console.log("Boss health:", boss);
